import os, json, time, sys
import numpy as np

# Import robust helpers persisted earlier
sys.path.append('storage/noesis/nmap')
try:
    from aggregator_utils_v2_1 import (
        robust_get_index_map, robust_load_contrib_boundary,
        robust_load_contrib_topk, is_crossings_only_filename
    )
except Exception:
    # Minimal fallbacks if helper module not found
    def robust_get_index_map(data): 
        return data.get('index_map_to_noesis') if isinstance(data, dict) else None
    def robust_load_contrib_boundary(data, idx_map):
        if not isinstance(data, dict): return set()
        out = set()
        for e in data.get('boundary', []):
            try:
                d = int(e['disc']); s = str(e['side'])
                if idx_map: d = idx_map[d]
                out.add((d, s))
            except Exception: pass
        return out
    def robust_load_contrib_topk(data, method_key):
        if not isinstance(data, dict): return []
        ents = []
        tk = data.get('topk')
        if isinstance(tk, list):
            for ent in tk:
                m = str(ent.get('method','')).lower()
                if (method_key=='slack' and m.startswith('slack')) or (method_key=='kkt' and m.startswith('kkt')):
                    ents.append(ent)
        if method_key=='slack':
            for k,v in list(data.items()):
                if isinstance(k,str) and k.startswith('slack_top_k_') and isinstance(v,list):
                    ents.append({'method':'slack','tol':k.replace('slack_top_k_','').replace('_','.'),'K':len(v),'pairs':v})
        return ents
    def is_crossings_only_filename(fname): return 'crossing' in fname.lower()

# Constants and paths
N = 26
SHARED_DIR = 'storage/shared/appxE_contribs'
OUT_DIR    = 'storage/noesis/nmap/results'
SUM_PATH   = 'storage/noesis/nmap/appendix_E_summary_v2_1.json'
FREEZE_DIR = 'storage/noesis/nmap/freezes'
AUDIT_SLACK = 'storage/noesis/nmap/results/noesis_internal_topk_audit.json'   # Eval 826
AUDIT_KKT   = 'storage/noesis/nmap/results/noesis_internal_kkt_topk_audit.json' # Eval 831
NOESIS_C = 'storage/noesis/latest_centers.txt'
NOESIS_R = 'storage/noesis/latest_radii.txt'

K_GRID = [15, 25, 40, 60]
TOLS = [1e-9, 1e-8]
BOUND_TOL = 2e-8

def load_json(path):
    with open(path, 'r') as f:
        return json.load(f)

def norm_tol(t):
    if isinstance(t,(int,float)): return float(t)
    if isinstance(t,str):
        t = t.replace('−','-').strip()
        try: return float(t)
        except: return None
    return None

def slacks(c, r):
    x = c[:,0]; y = c[:,1]
    return x - r, 1.0 - x - r, y - r, 1.0 - y - r

def boundary_set(c, r, tol):
    s_xL, s_xR, s_yB, s_yT = slacks(c, r)
    out = set()
    for i in range(N):
        if s_xL[i] <= tol: out.add((i,'xL'))
        if s_xR[i] <= tol: out.add((i,'xR'))
        if s_yB[i] <= tol: out.add((i,'yB'))
        if s_yT[i] <= tol: out.add((i,'yT'))
    return out

def jaccard(A, B):
    if not A and not B: return 1.0
    if not A or not B: return 0.0
    inter = len(A & B); uni = len(A | B)
    return inter/uni if uni>0 else 1.0

def pairs_to_set(pairs, idx_map):
    S = set()
    for p in pairs:
        try:
            i, j = int(p[0]), int(p[1])
            if idx_map: i, j = idx_map[i], idx_map[j]
            if i==j: continue
            if i>j: i, j = j, i
            S.add((i,j))
        except Exception: pass
    return S

def load_snapshot():
    if os.path.exists(NOESIS_C) and os.path.exists(NOESIS_R):
        c = np.loadtxt(NOESIS_C, dtype=float).reshape(N,2)
        r = np.loadtxt(NOESIS_R, dtype=float).reshape(N,)
        return c, r
    # conservative fallback
    centers = []
    radius = 0.08
    for i in range(5):
        for j in range(6):
            if len(centers) < N:
                centers.append([0.1+0.2*i, 0.1+0.15*j])
    return np.array(centers,float), np.full(N, radius, float)

def construct_packing():
    c0, r0 = load_snapshot()
    os.makedirs(OUT_DIR, exist_ok=True)
    os.makedirs(FREEZE_DIR, exist_ok=True)

    # Load audits if present
    slack_audit = load_json(AUDIT_SLACK) if os.path.exists(AUDIT_SLACK) else None
    kkt_audit   = load_json(AUDIT_KKT)   if os.path.exists(AUDIT_KKT)   else None

    B_noe = boundary_set(c0, r0, tol=BOUND_TOL)
    files = sorted([f for f in os.listdir(SHARED_DIR) if f.endswith('.json')])
    results = []
    eligible_entries = 0

    for fname in files:
        if 'template' in fname.lower() or fname.endswith('_example.json'):
            continue
        if is_crossings_only_filename(fname):
            results.append({'file': fname, 'note': 'crossings_only'})
            continue
        path = os.path.join(SHARED_DIR, fname)
        try:
            data = load_json(path)
        except Exception:
            results.append({'file': fname, 'error': 'json_load_failed'})
            continue
        if not isinstance(data, dict):
            results.append({'file': fname, 'error': 'json_not_dict'})
            continue

        idx_map = robust_get_index_map(data)

        # Boundary compare
        B_contrib = robust_load_contrib_boundary(data, idx_map)
        boundary = {
            'tol': BOUND_TOL,
            'noesis_count': len(B_noe),
            'contrib_count': len(B_contrib),
            'jaccard': jaccard(B_noe, B_contrib)
        }

        # Top-K comparisons
        entries_slack = []
        if slack_audit:
            for ent in robust_load_contrib_topk(data, 'slack'):
                t = norm_tol(ent.get('tol'))
                K = int(ent.get('K', len(ent.get('pairs',[]))))
                if t in TOLS and K in K_GRID:
                    S_contrib = pairs_to_set(ent.get('pairs',[]), idx_map)
                    try:
                        noe_pairs = slack_audit['topk_pairs'][str(t)][str(K)]
                    except Exception:
                        noe_pairs = []
                    S_noe = pairs_to_set(noe_pairs, None)
                    entries_slack.append({
                        'tol': t, 'K': K,
                        'contrib_size': len(S_contrib),
                        'noesis_size': len(S_noe),
                        'jaccard': jaccard(S_noe, S_contrib)
                    })

        entries_kkt = []
        if kkt_audit:
            for ent in robust_load_contrib_topk(data, 'kkt'):
                t = norm_tol(ent.get('tol'))
                K = int(ent.get('K', len(ent.get('pairs',[]))))
                if t in TOLS and K in K_GRID:
                    S_contrib = pairs_to_set(ent.get('pairs',[]), idx_map)
                    try:
                        noe_pairs = kkt_audit['topk_pairs'][str(t)][str(K)]
                    except Exception:
                        noe_pairs = []
                    S_noe = pairs_to_set(noe_pairs, None)
                    entries_kkt.append({
                        'tol': t, 'K': K,
                        'contrib_size': len(S_contrib),
                        'noesis_size': len(S_noe),
                        'jaccard': jaccard(S_noe, S_contrib)
                    })

        # Eligibility (v2.1): boundary complete AND slack lists include at least (tol,K) in {(1e-9,25),(1e-8,15)}
        have_1e9_25 = any(e['tol']==1e-9 and e['K']==25 for e in entries_slack)
        have_1e8_15 = any(e['tol']==1e-8 and e['K']==15 for e in entries_slack)
        eligible = (boundary['contrib_count']==20) and have_1e9_25 and have_1e8_15
        if eligible: eligible_entries += 1

        results.append({
            'file': fname,
            'index_map_present': (idx_map is not None),
            'boundary': boundary,
            'topk_slack': {'entries': entries_slack},
            'topk_kkt': {'entries': entries_kkt},
            'eligible_v2_1': eligible
        })

    summary = {
        'status': 'ok',
        'schema_version': '1.1',
        'aggregator_version': '2.1',
        'files_seen': len(files),
        'stems_processed': len(results),
        'eligible_entries': eligible_entries,
        'generated_at': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
        'k_grid': K_GRID,
        'tols': TOLS,
        'boundary_tol': BOUND_TOL,
        'results': results
    }
    with open(SUM_PATH, 'w') as f:
        json.dump(summary, f, indent=2)
    with open(os.path.join(FREEZE_DIR, f'appendix_E_summary_v2_1_refresh_{summary["generated_at"]}.json'), 'w') as f:
        json.dump(summary, f, indent=2)

    # Return Noesis baseline with tiny shrink
    r = np.maximum(r0 - 1e-9, 1e-12)
    return c0.astype(float), r.astype(float)
